          "onEvent": {
            "change": {
              "actions": [
                {
                  "actionType": "toast",
                  "args": {
                    "msgType": "warning",
                    "msg": "任务${switch === true ? '派发' : '取消'}成功，等待后台操作..."
                  }
                },
                {
                  "actionType": "setValue",
                  "componentId": "demo-form",
                  "args": {
                    "value": {
                      "isFetching": true
                    }
                  }
                },
                {
                  "actionType": "ajax",
                  "api": {
                    "url": "/api/mock2/form/saveForm?waitSeconds=3",
                    "method": "get",
                    "messages": {
                      "success": "操作成功",
                      "failed": "操作失败"
                    }
                  }
                },
                {
                  "actionType": "setValue",
                  "componentId": "demo-form",
                  "args": {
                    "value": {
                      "isFetching": false
                    }
                  }
                }
              ]
            }
          }
        }
      ]
    }
  ]
