  "api": "/api/mock2/sample?perPage=10",
  "body": [
    {
      "type": "table",
      "source": "$rows",
      "columns": [
        {
          "name": "id",
          "label": "ID",
          "searchable": true
        },
        {
          "name": "engine",
          "label": "Rendering engine",
          "filterable": {
            "options": [
              "Internet Explorer 4.0",
              "Internet Explorer 5.0"
            ]
          },
          "onEvent": {
            "click": {
              "actions": [
                {
                  "actionType": "toast",
                  "args": {
                    "msgType": "info",
                    "msg": "第${event.data.index}行的${event.data.engine}"
                  }
                }
              ]
            }
          }
        },
        {
          "name": "browser",
          "label": "Browser",
          "sortable": true,
          "onEvent": {
            "mouseenter": {
              "actions": [
                {
                  "actionType": "toast",
                  "args": {
                    "msgType": "info",
                    "msg": "第${event.data.index}行的${event.data.browser}"
                  }
                }
              ]
            },
            "mouseleave": {
              "actions": [
                {
                  "actionType": "toast",
                  "args": {
                    "msgType": "info",
                    "msg": "第${event.data.index}行的${event.data.browser}"
                  }
                }
              ]
            }
          }
        },
        {
          "name": "platform",
          "label": "Platform(s)"
        },
        {
          "name": "version",
          "label": "Engine version"
        },
        {
          "name": "grade",
          "label": "CSS grade"
        }
      ]
    }
  ]
}

